window.NARRATION = window.NARRATION || {};
Object.assign(window.NARRATION, {"What do you think will roll out of the box?":{"src":"audio/198a2debb377abb7.mp3","starts":[0,0.209,0.29,0.418,0.662,0.848,1.057,1.184,1.277,1.382]},"The Very Busy Little Robot.":{"src":"audio/d841ec4db78b12b1.mp3","starts":[0,0.255,0.592,0.882,1.138]},"In the quiet workshop, a little green light blinked on. Beep.":{"src":"audio/4083d0558c7e1783.mp3","starts":[0,0.197,0.348,0.801,1.695,1.846,2.125,2.415,2.635,3.007,3.704]},"On Tuesday he found two spinning blue gears. Whir, whir!":{"src":"audio/be1613b3bddb0dd6.mp3","starts":[0,0.232,0.755,0.917,1.161,1.405,1.834,2.078,2.705,3.39]},"On Monday he found one shiny red battery. Click! But his engine was still hungry.":{"src":"audio/e2c9b2f4d14a0579.mp3","starts":[0,0.232,0.569,0.731,1.033,1.324,1.753,1.962,2.612,3.68,3.889,4.075,4.377,4.505,4.795]},"On Wednesday he found three bouncy yellow springs. Boing, boing, boing!":{"src":"audio/89954d66fed20eaf.mp3","starts":[0,0.244,0.836,0.998,1.265,1.579,1.974,2.264,3.146,3.936,4.69]},"What did the robot find on Tuesday?":{"src":"audio/cc317e903c1fe822.mp3","starts":[0,0.255,0.395,0.546,0.987,1.277,1.405]},"On Thursday he found four twisting green bolts. Squeak, squeak, squeak, squeak!":{"src":"audio/94add0e38c7aabe3.mp3","starts":[0,0.255,0.824,0.987,1.289,1.579,1.974,2.218,2.879,3.425,3.913,4.377]},"On Friday he found five glowing purple wires. Zap, zap, zap, zap, zap!":{"src":"audio/2f8609eabaa62ca3.mp3","starts":[0,0.267,0.743,0.894,1.196,1.591,1.974,2.31,3.193,3.889,4.574,5.178,5.782]},"He is still hungry. What might he do on Saturday?":{"src":"audio/be0ff838e9fd8c95.mp3","starts":[0,0.232,0.36,0.72,1.428,1.649,1.858,2.009,2.194,2.368]},"On Saturday he attached one magnet, two sirens, three tracks, four antennas, and five bells.":{"src":"audio/a58e7fc94e87f59a.mp3","starts":[0,0.267,0.848,1.01,1.474,1.776,2.415,2.705,3.541,3.855,4.656,4.957,5.817,6.13,6.525]},"Bzzzt! He was too heavy, too loud, and too bright. He had a system overload.":{"src":"audio/89e2a6cf6c547123.mp3","starts":[0,0.778,0.975,1.149,1.393,1.753,1.985,2.322,2.473,2.659,3.007,3.146,3.297,3.379,3.727]},"What does overload mean?":{"src":"audio/4bad01eba851ad72.mp3","starts":[0,0.232,0.453,0.987]},"Why couldn't the robot move?":{"src":"audio/958dddcf932dac3e.mp3","starts":[0,0.313,0.58,0.697,1.103]},"On Sunday he unhooked the extra parts and took a long drink from one golden oil can.":{"src":"audio/4f923e7fc3d3ddff.mp3","starts":[0,0.267,0.708,0.871,1.184,1.3,1.591,1.927,2.125,2.334,2.415,2.717,2.972,3.158,3.332,3.657,3.971]},"He rolled into his charging pod for three quiet days, and his new parts began to fuse.":{"src":"audio/2c9138f7c8d37071.mp3","starts":[0,0.279,0.557,0.801,0.952,1.44,1.753,1.962,2.276,2.682,3.518,3.738,3.924,4.133,4.481,4.795,4.934]},"Then he powered on and pushed the doors open. Swoosh!":{"src":"audio/4416361facb78434.mp3","starts":[0,0.267,0.418,0.836,1.01,1.138,1.393,1.498,1.869,2.45]},"He was not a clunky grey robot any more. He was a zooming, rainbow hover-bot.":{"src":"audio/969fab4b5d5c8889.mp3","starts":[0,0.232,0.406,0.58,0.697,1.161,1.451,1.916,2.136,2.81,3.007,3.204,3.309,4.087,4.609,4.946]},"What came first — the oil can, the red battery, or the hover-bot?":{"src":"audio/34b5c1afe615a423.mp3","starts":[0,0.29,0.592,1.289,1.474,1.834,2.426,2.624,2.856,3.425,3.634,3.738,3.982]},"How do you think he felt when he flew?":{"src":"audio/0f5cd6a253ebfc39.mp3","starts":[0,0.221,0.313,0.43,0.639,0.778,0.998,1.149,1.265]},"Look at the pictures. Tell the story in the right order.":{"src":"audio/d8e1e1c51d498887.mp3","starts":[0,0.279,0.36,0.476,1.219,1.463,1.579,1.939,2.02,2.136,2.368]},"He was not a hungry little robot any more. He had learned when enough was enough.":{"src":"audio/96410621fe93aef3.mp3","starts":[0,0.244,0.511,0.824,0.906,1.242,1.486,1.916,2.136,2.833,3.03,3.216,3.483,3.657,3.913,4.098]},"The hover-bot zoomed away, light, and glad.":{"src":"audio/f71c02a277fa8908.mp3","starts":[0,0.197,0.488,0.778,1.103,1.637,1.927,2.136]},"Noah's Gentle Hands.":{"src":"audio/469faac25e9417c1.mp3","starts":[0,0.464,0.778]},"Noah sat at the table. He made a blue snail out of plasticine.":{"src":"audio/45f8be71b60d5f13.mp3","starts":[0,0.406,0.627,0.731,0.836,1.533,1.765,1.985,2.055,2.334,2.647,2.786,2.891]},"His baby sister crawled over. She grabbed his blue plasticine!":{"src":"audio/a627a252648b62cd.mp3","starts":[0,0.29,0.615,0.975,1.289,1.834,2.055,2.345,2.461,2.67]},"How do you think Noah feels?":{"src":"audio/2bc944c08605e1bf.mp3","starts":[0,0.244,0.337,0.453,0.72,1.022]},"Noah felt hot and cross. He wanted to push her away.":{"src":"audio/b76d9f6bf8215b37.mp3","starts":[0,0.418,0.697,0.998,1.184,1.974,2.159,2.45,2.554,2.775,2.914]},"But Noah kept his hands to himself. Pushing can hurt a baby.":{"src":"audio/229f84f9505a5251.mp3","starts":[0,0.255,0.546,0.778,0.906,1.207,1.37,2.032,2.473,2.647,2.833,2.914]},"Why should Noah not push his baby sister?":{"src":"audio/3baab9e50834f614.mp3","starts":[0,0.302,0.546,0.836,1.01,1.219,1.37,1.683]},"He put a hand on his tummy. He took one slow, deep breath.":{"src":"audio/afb056d4bbba9006.mp3","starts":[0,0.209,0.406,0.488,0.731,0.848,0.987,1.556,1.741,2.043,2.426,3.181,3.576]},"Then another. His body felt calm again.":{"src":"audio/4c7eae87ad2ea455.mp3","starts":[0,0.29,1.091,1.347,1.672,1.916,2.241]},"What did Noah do to feel calm?":{"src":"audio/580ce1e0d9b57d30.mp3","starts":[0,0.232,0.383,0.65,0.789,0.894,1.149]},"What do you think Mama will do?":{"src":"audio/1d120995ef7d4717.mp3","starts":[0,0.232,0.325,0.453,0.685,0.964,1.149]},"Noah used his words. \"Mama, she took my plasticine. Can you help?\"":{"src":"audio/1f024eb3168f738b.mp3","starts":[0,0.43,0.697,0.848,1.846,2.659,2.844,3.053,3.181,4.203,4.412,4.563]},"Mama gave the baby a soft rattle. Plasticine is not safe for babies.":{"src":"audio/20a1818745e6719f.mp3","starts":[0,0.348,0.546,0.65,0.987,1.103,1.474,2.31,3.135,3.297,3.564,3.889,4.052]},"Noah got his blue plasticine back. He smiled.":{"src":"audio/c6d6f5c780f2c6f2.mp3","starts":[0,0.395,0.604,0.755,1.022,1.741,2.299,2.496]},"What does calm mean?":{"src":"audio/3afe736f172ab321.mp3","starts":[0,0.267,0.511,0.882]},"What came first — the deep breath, or asking Mama?":{"src":"audio/abfb97bd318141aa.mp3","starts":[0,0.29,0.569,1.231,1.37,1.591,1.985,2.229,2.601]},"How do you think Noah felt at the end?":{"src":"audio/5340a9e38e08ee40.mp3","starts":[0,0.255,0.348,0.476,0.743,1.045,1.254,1.358,1.521]},"Noah made his snail. His sister shook her rattle. They played side by side.":{"src":"audio/d5207d93ca39b640.mp3","starts":[0,0.383,0.58,0.731,1.637,1.834,2.218,2.485,2.647,3.425,3.634,3.959,4.284,4.505]},"When Noah feels cross, he keeps gentle hands, takes a breath, and uses his words.":{"src":"audio/9d548e4fb2164ca1.mp3","starts":[0,0.29,0.604,0.929,1.718,1.869,2.194,2.554,3.286,3.622,3.692,4.389,4.632,5.016,5.178]},"The Very Hungry Snail.":{"src":"audio/694f150786ec06ea.mp3","starts":[0,0.279,0.639,0.964]},"On Sunday morning, a tiny egg sat on a quiet leaf.":{"src":"audio/d51c593c8738c2c2.mp3","starts":[0,0.255,0.615,1.173,1.358,1.776,2.009,2.345,2.485,2.589,3.019]},"What do you think will hatch from the egg?":{"src":"audio/be78b6ce7e19d9f1.mp3","starts":[0,0.221,0.302,0.43,0.639,0.836,1.091,1.265,1.405]},"On Monday the egg cracked. Out came a snail no bigger than a pea.":{"src":"audio/0478b87da348e832.mp3","starts":[0,0.232,0.58,0.72,0.94,1.672,1.916,2.125,2.241,2.682,2.833,3.077,3.228,3.332]},"He was hungry. On Monday he ate one sweet strawberry.":{"src":"audio/f8e7f1697dfb05d4.mp3","starts":[0,0.232,0.418,1.149,1.393,1.73,1.858,2.055,2.229,2.485]},"On Tuesday he ate two plump blueberries.":{"src":"audio/72ac304b996c1b41.mp3","starts":[0,0.232,0.731,0.859,1.057,1.265,1.509]},"On Wednesday he ate three soft mushrooms.":{"src":"audio/6fdda90b7f48e13e.mp3","starts":[0,0.221,0.708,0.836,1.033,1.347,1.73]},"What did the snail eat on Tuesday?":{"src":"audio/5cfacd9a8cc460c2.mp3","starts":[0,0.232,0.372,0.488,0.824,0.964,1.08]},"On Thursday he ate four round peas.":{"src":"audio/3c454d85b4493fce.mp3","starts":[0,0.244,0.766,0.906,1.126,1.358,1.625]},"On Friday he ate five ripe raspberries.":{"src":"audio/c8eee3313541027d.mp3","starts":[0,0.255,0.731,0.859,1.057,1.393,1.625]},"On Saturday he ate an enormous feast: a leaf, a plum, a bean, and a whole cucumber.":{"src":"audio/8359d0b57e06c1d2.mp3","starts":[0,0.267,0.836,0.998,1.219,1.347,1.95,2.821,3.03,3.68,3.901,4.737,4.957,5.689,5.921,6.002,6.339]},"What does enormous mean?":{"src":"audio/aa027ceacffdc5bc.mp3","starts":[0,0.244,0.418,0.859]},"That night his tummy ached. He had eaten far too much.":{"src":"audio/b5411383b895a0bf.mp3","starts":[0,0.36,0.627,0.813,1.207,1.985,2.183,2.345,2.647,2.949,3.158]},"Why did his tummy hurt?":{"src":"audio/5ea6efeb198134ce.mp3","starts":[0,0.255,0.395,0.534,0.917]},"On Sunday he rested on a cool stone and sipped a drop of dew.":{"src":"audio/4fcaabfa7632abeb.mp3","starts":[0,0.267,0.72,0.882,1.231,1.335,1.44,1.741,2.183,2.415,2.705,2.775,3.065,3.204]},"After a long rest he felt better. His shell had grown into a beautiful spiral.":{"src":"audio/15299df50447aa6f.mp3","starts":[0,0.372,0.464,0.766,1.01,1.126,1.358,2.159,2.38,2.659,2.833,3.088,3.332,3.425,3.855]},"What came first — the feast, the egg, or the spiral shell?":{"src":"audio/bd89c15583c4b017.mp3","starts":[0,0.279,0.546,1.149,1.3,1.927,2.136,2.577,2.775,2.868,3.274]},"How do you think the snail felt when his shell grew?":{"src":"audio/110b137806b56e40.mp3","starts":[0,0.209,0.313,0.441,0.662,0.789,1.149,1.37,1.544,1.707,2.009]},"He was not a tiny snail any more. He had learned to listen to his tummy.":{"src":"audio/e4c43e8ab7f48481.mp3","starts":[0,0.232,0.43,0.627,0.697,1.022,1.312,1.486,2.067,2.287,2.461,2.705,2.81,3.077,3.216,3.355]},"The snail slid slowly home, full, and glad.":{"src":"audio/bcfee49b8d367288.mp3","starts":[0,0.232,0.592,0.882,1.358,1.962,2.589,2.844]},"Noah and the Shadow.":{"src":"audio/658f9e1c3a6b28a7.mp3","starts":[0,0.418,0.557,0.673]},"It was bedtime. The room was dark and quiet.":{"src":"audio/58578570eb195033.mp3","starts":[0,0.186,0.395,1.207,1.37,1.579,1.765,2.078,2.241]},"Noah saw a big shape on the wall. His tummy felt wobbly.":{"src":"audio/944a01a39824681d.mp3","starts":[0,0.406,0.65,0.731,0.964,1.242,1.347,1.451,2.032,2.276,2.624,2.868]},"What do you think the big shape really is?":{"src":"audio/907fca90f3241e9b.mp3","starts":[0,0.221,0.302,0.418,0.627,0.755,0.975,1.231,1.509]},"Noah did not hide. He called, \"Mama, can you come?\"":{"src":"audio/198b6641d8992c92.mp3","starts":[0,0.36,0.522,0.743,1.184,1.393,1.95,2.357,2.531,2.67]},"What was the big shape?":{"src":"audio/52e4c7e2adb43d4b.mp3","starts":[0,0.221,0.395,0.522,0.789]},"Mama turned on a little nightlight. The shape was only his coat on the chair!":{"src":"audio/2345703087df130a.mp3","starts":[0,0.372,0.662,0.778,0.859,1.115,2.09,2.276,2.601,2.821,3.135,3.332,3.599,3.704,3.82]},"\"It is just a shadow,\" said Mama. Noah took a slow breath.":{"src":"audio/972c337dee64cdeb.mp3","starts":[0.058,0.209,0.372,0.662,0.743,1.428,1.683,2.554,2.914,3.135,3.251,3.646]},"What is a shadow?":{"src":"audio/965b8dc8d0fd751f.mp3","starts":[0,0.244,0.372,0.453]},"Why did the nightlight help Noah?":{"src":"audio/71ad3758d04a0e0e.mp3","starts":[0,0.244,0.383,0.499,0.894,1.173]},"Noah hugged his teddy. The nightlight glowed softly. He fell asleep.":{"src":"audio/4b0bffda484706a6.mp3","starts":[0,0.383,0.65,0.801,1.556,1.753,2.183,2.496,3.587,3.808,4.063]},"How did Noah feel at the end?":{"src":"audio/1b571a0b9c2bde9f.mp3","starts":[0,0.232,0.383,0.662,0.882,0.987,1.149]},"When Noah feels scared, he calls for help and takes a slow breath.":{"src":"audio/c33b2248bd93ba9d.mp3","starts":[0,0.267,0.557,0.824,1.718,1.892,2.218,2.403,2.775,3.019,3.32,3.413,3.808]},"Noah Shares His Snack.":{"src":"audio/d8b33e7bf61d731a.mp3","starts":[0,0.383,0.72,0.882]},"Noah had a bowl of soft banana slices. Yum!":{"src":"audio/7d7ee57d9427ecb2.mp3","starts":[0,0.418,0.58,0.673,0.964,1.091,1.405,1.8,2.496]},"Baby sister sat in her high chair. She reached for the bowl.":{"src":"audio/f3d10f25a882c2be.mp3","starts":[0,0.406,0.789,1.01,1.126,1.277,1.486,2.101,2.322,2.601,2.74,2.844]},"Baby sister wants some banana. What could Noah do?":{"src":"audio/e58857d9b5c0c0f6.mp3","starts":[0,0.406,0.72,0.94,1.103,1.892,2.101,2.287,2.589]},"Noah gave her one slice. Then another. He shared.":{"src":"audio/a5bc8b69ab10e55b.mp3","starts":[0,0.395,0.627,0.813,1.057,1.741,1.997,2.798,3.042]},"What did Noah share?":{"src":"audio/117b07e5891764af.mp3","starts":[0,0.255,0.441,0.766]},"Mama smiled. \"That was kind, Noah.\"":{"src":"audio/3707d3c64ca21b92.mp3","starts":[0,0.36,1.219,1.474,1.695,2.043]},"Noah and his sister ate their snack together.":{"src":"audio/e5dbd2575e12d104.mp3","starts":[0,0.372,0.511,0.639,1.057,1.265,1.463,1.776]},"What does shared mean?":{"src":"audio/5f5a274ab0cd93f3.mp3","starts":[0,0.244,0.43,0.778]},"Why did Noah still have a snack after sharing?":{"src":"audio/731b4cd1c530919c.mp3","starts":[0,0.244,0.406,0.72,0.975,1.138,1.254,1.718,2.02]},"How did baby sister feel?":{"src":"audio/ec6aa5b11cd2f123.mp3","starts":[0,0.221,0.372,0.662,1.022]},"Sharing made two happy tummies.":{"src":"audio/63f5d6edb66e9cc9.mp3","starts":[0,0.453,0.673,0.964,1.265]},"Noah Says Sorry.":{"src":"audio/b263bc0391864e9c.mp3","starts":[0,0.418,0.673]},"Look where the car is going. What do you think will happen?":{"src":"audio/36bfe24c081d7322.mp3","starts":[0,0.267,0.43,0.546,0.789,0.952,1.625,1.788,1.869,1.985,2.183,2.357]},"Baby sister made a tower of soft blocks. Noah zoomed his car across the rug.":{"src":"audio/f84ec6cd34ac90c3.mp3","starts":[0,0.406,0.801,0.987,1.068,1.486,1.625,1.985,3.03,3.413,3.704,3.878,4.145,4.54,4.667]},"Crash! The car hit the tower. The blocks fell down.":{"src":"audio/f2b28587bde802c9.mp3","starts":[0,1.115,1.312,1.602,1.776,1.892,2.601,2.786,3.228,3.518]},"Baby sister cried. Noah did not mean to do it. It was an accident.":{"src":"audio/add373be16f5a5f1.mp3","starts":[0,0.395,0.743,1.382,1.753,1.904,2.148,2.438,2.589,2.81,3.146,3.32,3.483,3.646]},"Noah knelt down. He patted her back gently. \"I am sorry,\" he said.":{"src":"audio/f1cdcf733cafc46b.mp3","starts":[0,0.383,0.627,1.324,1.544,1.927,2.067,2.334,3.228,3.437,3.657,4.331,4.481]},"What did Noah say to his sister?":{"src":"audio/df072335f0bcd7b4.mp3","starts":[0,0.244,0.418,0.731,0.906,1.022,1.161]},"What does accident mean?":{"src":"audio/a37ad1a547fe22a8.mp3","starts":[0,0.244,0.476,0.964]},"Then Noah helped her build the tower again.":{"src":"audio/dad5107f69693e00.mp3","starts":[0,0.279,0.569,0.813,0.952,1.173,1.289,1.683]},"Why did Noah say sorry, if it was an accident?":{"src":"audio/03ef16672e263a96.mp3","starts":[0,0.255,0.418,0.708,0.964,1.544,1.73,1.823,1.974,2.09]},"What came first — saying sorry, or building again?":{"src":"audio/38c53d1ee6b60df3.mp3","starts":[0,0.267,0.522,0.882,1.184,1.776,1.985,2.357]},"The new tower was even taller. Baby sister clapped.":{"src":"audio/c69d4e15acbcc89f.mp3","starts":[0,0.255,0.488,0.894,1.115,1.451,2.171,2.543,2.902]},"Even after an accident, Noah says sorry and helps fix it.":{"src":"audio/015734c738eed0dd.mp3","starts":[0,0.313,0.569,0.673,1.149,1.428,1.66,2.043,2.159,2.473,2.833]},"Noah Tidies Up.":{"src":"audio/bea0d185321f814c.mp3","starts":[0,0.383,0.813]},"Blocks, cars, and crayons were all over the rug. What a mess!":{"src":"audio/c570664943752287.mp3","starts":[0,0.639,1.173,1.382,1.974,2.194,2.45,2.659,2.786,3.262,3.483,3.564]},"Noah did not want to tidy. It looked like too much.":{"src":"audio/c44186d6b5cf15a0.mp3","starts":[0,0.383,0.546,0.731,0.929,1.033,1.649,1.765,1.974,2.125,2.334]},"How could Noah make the big job feel smaller?":{"src":"audio/8f0bae28545182e0.mp3","starts":[0,0.279,0.476,0.743,0.929,1.08,1.335,1.637,1.904]},"So Noah started small. First, just the blocks. Clunk, clunk, into the basket.":{"src":"audio/18065559955c96fa.mp3","starts":[0,0.29,0.604,0.998,1.707,2.519,2.821,2.926,3.785,4.586,5.329,5.631,5.747]},"What did Noah put away first?":{"src":"audio/be8a663383e0cea0.mp3","starts":[0,0.255,0.43,0.72,0.894,1.161]},"Baby sister wanted to help. She dropped in a soft toy. Plop!":{"src":"audio/db7c8a65d4b704bd.mp3","starts":[0,0.372,0.697,0.964,1.068,1.602,1.8,2.136,2.241,2.322,2.705,3.297]},"Soon the rug was clean. Noah felt proud.":{"src":"audio/b9bc7eb85b98dc6b.mp3","starts":[0,0.325,0.441,0.65,0.836,1.382,1.776,2.032]},"What does proud mean?":{"src":"audio/d51fd3d04e494c42.mp3","starts":[0,0.244,0.464,0.801]},"Why did starting with just the blocks help?":{"src":"audio/0b4668b03c8e32f1.mp3","starts":[0,0.313,0.511,0.894,1.057,1.265,1.37,1.753]},"What came first — the blocks, or sister's soft toy?":{"src":"audio/22b14588ee9761ef.mp3","starts":[0,0.302,0.569,1.184,1.312,1.974,2.206,2.577,2.891]},"A big job is easy when you do one small part at a time.":{"src":"audio/f2786fc607270819.mp3","starts":[0,0.197,0.441,0.778,0.964,1.277,1.428,1.556,1.788,2.009,2.368,2.589,2.694,2.786]},"Noah Waits His Turn.":{"src":"audio/a47507455aba2ec5.mp3","starts":[0,0.418,0.697,0.882]},"Noah ran to the slide. A girl in a red coat was there first.":{"src":"audio/0c13ccdc3360aa6f.mp3","starts":[0,0.395,0.615,0.731,0.848,1.695,1.881,2.136,2.241,2.322,2.543,2.833,2.995,3.239]},"Noah wants to slide now. What do you think he will do?":{"src":"audio/ab6a5fb3378d9493.mp3","starts":[0,0.383,0.627,0.755,1.126,1.579,1.765,1.846,1.997,2.229,2.334,2.543]},"Noah wanted to go first. But it was her turn.":{"src":"audio/9351e72a6a9c3045.mp3","starts":[0,0.418,0.685,0.789,1.022,1.672,1.834,1.927,2.101,2.322]},"What did Noah do while he waited?":{"src":"audio/9cd7f214279cf6fd.mp3","starts":[0,0.267,0.418,0.697,0.882,1.091,1.207]},"So Noah waited. He counted on his fingers. One, two, three, four, five.":{"src":"audio/21b6fa17ad8f19a6.mp3","starts":[0,0.29,0.604,1.416,1.625,1.985,2.101,2.252,3.146,3.796,4.574,5.329,6.177]},"Whoosh! The girl slid down. Now it was Noah's turn.":{"src":"audio/b4990debf83f6ca3.mp3","starts":[0,0.906,1.08,1.347,1.649,2.252,2.485,2.589,2.786,3.146]},"Noah climbed up and slid down. Whee!":{"src":"audio/1049d9e216f47cf5.mp3","starts":[0,0.406,0.778,0.929,1.068,1.358,1.974]},"Why did Noah have to wait?":{"src":"audio/754668970be7d0a8.mp3","starts":[0,0.255,0.418,0.65,0.836,0.952]},"What does turn mean?":{"src":"audio/5a1cbbc44fd1f11e.mp3","starts":[0,0.255,0.453,0.755]},"What came first — counting, or sliding?":{"src":"audio/c4b26290ed1cf339.mp3","starts":[0,0.255,0.511,1.149,1.556,1.695]},"How do you think the girl felt when Noah waited?":{"src":"audio/c8a1ba797df97ffe.mp3","starts":[0,0.221,0.313,0.43,0.627,0.755,1.022,1.242,1.428,1.741]},"The girl smiled at Noah. Waiting made a new friend.":{"src":"audio/90c20eb59e1d5d1a.mp3","starts":[0,0.232,0.476,0.871,0.975,1.544,1.974,2.171,2.252,2.438]},"When it is not his turn yet, Noah waits and counts.":{"src":"audio/ff8bfd4c9bb86519.mp3","starts":[0,0.279,0.383,0.569,0.859,1.057,1.347,1.73,2.136,2.531,2.74]},"Seven Quiet Lands.":{"src":"audio/99213c0f103f0e96.mp3","starts":[0,0.464,0.882]},"A little paper boat sat on a round globe.":{"src":"audio/e0c6899758134344.mp3","starts":[0,0.174,0.43,0.731,0.964,1.184,1.3,1.37,1.614]},"The boat is ready to sail. Which land do you think he will see first?":{"src":"audio/4088e323f2e34249.mp3","starts":[0,0.232,0.453,0.615,0.871,1.022,1.73,2.02,2.252,2.345,2.473,2.705,2.81,2.995,3.204]},"First he sailed to Africa. The land was wide and warm.":{"src":"audio/c05d896085d38046.mp3","starts":[0,0.337,0.441,0.697,0.836,1.637,1.823,2.078,2.287,2.694,2.844]},"Next he sailed to Antarctica. The land was white and still.":{"src":"audio/528a36d045613fd4.mp3","starts":[0,0.383,0.476,0.743,0.848,1.904,2.101,2.38,2.589,2.868,3.042]},"Which land was white and still?":{"src":"audio/1306540882553231.mp3","starts":[0,0.313,0.534,0.697,0.929,1.103]},"Then he sailed to Asia. The land was vast, with high mountains.":{"src":"audio/b11804c468a173d3.mp3","starts":[0,0.29,0.453,0.731,0.859,1.718,1.939,2.218,2.438,2.902,3.111,3.344]},"He sailed to Australia. A red rock rose in a quiet desert.":{"src":"audio/1e59a0ae4b8ccb6e.mp3","starts":[0,0.221,0.476,0.58,1.498,1.695,1.95,2.252,2.508,2.601,2.682,3.077]},"He sailed to Europe. Green fields met a grey sea.":{"src":"audio/ba73402171e1f700.mp3","starts":[0,0.232,0.522,0.65,1.254,1.579,1.939,2.101,2.183,2.519]},"He sailed to North America. Tall trees stood by a cool lake.":{"src":"audio/fa82151a364d9508.mp3","starts":[0,0.244,0.534,0.639,0.882,1.707,2.055,2.334,2.589,2.786,2.914,3.216]},"He sailed to South America. A long river ran through a green forest.":{"src":"audio/e17dfd656329b90a.mp3","starts":[0,0.232,0.511,0.615,0.859,1.869,2.055,2.415,2.752,2.972,3.239,3.309,3.657]},"He had visited seven continents.":{"src":"audio/1a812e65e983e6f7.mp3","starts":[0,0.197,0.383,0.813,1.184]},"He has seen all seven lands. What might he do now?":{"src":"audio/7966e629408e8605.mp3","starts":[0,0.267,0.441,0.685,0.894,1.289,2.009,2.206,2.403,2.543,2.717]},"What does continent mean?":{"src":"audio/01e5c1717cd460ad.mp3","starts":[0,0.244,0.476,0.975]},"Why did the little boat stop sailing?":{"src":"audio/56661016080e1438.mp3","starts":[0,0.267,0.418,0.546,0.836,1.103,1.474]},"What came first — Antarctica, the globe, or Australia?":{"src":"audio/1a29094464045dda.mp3","starts":[0,0.29,0.569,1.277,2.322,2.473,3.123,3.344]},"How do you think he felt when the trip was done?":{"src":"audio/ceb61ee48fc15fdb.mp3","starts":[0,0.244,0.337,0.464,0.673,0.836,1.057,1.219,1.324,1.591,1.8]},"He was not lost. He had learned the seven quiet lands.":{"src":"audio/ca2996a0f510ea7e.mp3","starts":[0,0.232,0.43,0.673,1.509,1.73,1.916,2.159,2.276,2.647,3.042]},"The little boat folded his sail and rested.":{"src":"audio/da6c9b8ab33c2177.mp3","starts":[0,0.209,0.488,0.743,1.126,1.254,1.672,1.927]},"Out rolled a tiny grey robot. His battery blinked low, and he was hungry for parts.":{"src":"audio/47714796a69a52c6.mp3","starts":[0,0.325,0.627,0.72,1.126,1.44,2.531,2.821,3.239,3.564,4.145,4.365,4.493,4.702,5.074,5.259]},"The Little Rocket and the Nine Planets.":{"src":"audio/ddf4eaaa938a1cd6.mp3","starts":[0,0.244,0.534,0.906,1.033,1.149,1.428]},"The rocket wants to visit every planet. Which one do you think is closest to the Sun?":{"src":"audio/4394387327d3d5bf.mp3","starts":[0,0.267,0.627,0.871,0.987,1.312,1.602,2.461,2.74,2.879,2.972,3.1,3.344,3.483,3.889,4.017,4.145]},"First he flew to Mercury. It was small, grey, and very close to the Sun.":{"src":"audio/f6978e4ef398a39a.mp3","starts":[0,0.348,0.441,0.65,0.766,1.486,1.66,1.811,2.589,3.309,3.576,3.913,4.191,4.319,4.435]},"Next he flew to Venus. Thick yellow clouds wrapped it up.":{"src":"audio/f866e5c0c943a219.mp3","starts":[0,0.383,0.488,0.697,0.801,1.556,1.858,2.183,2.496,2.775,2.879]},"Which planet is our home?":{"src":"audio/6f9f688c3e803c77.mp3","starts":[0,0.302,0.627,0.731,0.906]},"Then he flew past Earth. Blue sea, green land. That is our home.":{"src":"audio/2da5456dd6b4ef56.mp3","starts":[0,0.267,0.395,0.627,0.998,1.509,1.904,2.508,2.879,3.495,3.762,3.889,4.075]},"He flew to Mars. The ground was red and dusty.":{"src":"audio/100c183dd0ae42b7.mp3","starts":[0,0.221,0.464,0.569,1.184,1.358,1.649,1.858,2.078,2.194]},"He flew to Jupiter. It was huge, the biggest planet of all.":{"src":"audio/af2d5257b7834261.mp3","starts":[0,0.232,0.488,0.627,1.37,1.544,1.741,2.496,2.659,2.972,3.332,3.448]},"He flew to Saturn. Wide, flat rings went all the way around it.":{"src":"audio/1d14f209106aafe0.mp3","starts":[0,0.221,0.441,0.557,1.335,1.741,2.125,2.473,2.67,2.844,2.961,3.123,3.471]},"Which planet had wide rings around it?":{"src":"audio/7308606dd86e3aed.mp3","starts":[0,0.325,0.685,0.882,1.207,1.463,1.8]},"He flew to Uranus. It was pale blue, and it spun on its side.":{"src":"audio/51b0ad305f70879f.mp3","starts":[0,0.232,0.453,0.557,1.393,1.556,1.741,2.078,2.635,2.856,2.984,3.402,3.518,3.692]},"He flew to Neptune. It was deep blue, cold, and far away.":{"src":"audio/e4e4be7760174423.mp3","starts":[0,0.221,0.441,0.546,1.312,1.474,1.66,1.892,2.496,3.053,3.332,3.587]},"Last, he flew to little Pluto. It is a dwarf planet, tiny and icy.":{"src":"audio/e7a60874444e10ea.mp3","starts":[0,0.476,0.615,0.836,0.952,1.196,1.974,2.159,2.287,2.357,2.682,3.111,3.564,3.727]},"He has seen all nine. What might he do now?":{"src":"audio/4dad6a0b7950a586.mp3","starts":[0,0.267,0.441,0.673,0.894,1.393,1.591,1.765,1.904,2.078]},"He had visited eight planets and one dwarf planet.":{"src":"audio/3252eb495a4fd45c.mp3","starts":[0,0.221,0.406,0.871,1.115,1.741,2.009,2.218,2.543]},"What does planet mean?":{"src":"audio/42d25b55c74f48a7.mp3","starts":[0,0.244,0.43,0.789]},"Why was Neptune so cold?":{"src":"audio/9f4af30bba42b3b7.mp3","starts":[0,0.302,0.522,0.906,1.115]},"What came first — Mars, Mercury, or Saturn?":{"src":"audio/d2d71460aeb63660.mp3","starts":[0,0.267,0.534,1.242,1.858,2.426,2.612]},"How do you think he felt so far from home?":{"src":"audio/0119b10cdc2a0ebf.mp3","starts":[0,0.221,0.313,0.43,0.627,0.778,1.033,1.254,1.451,1.66]},"Look at the pictures. Tell the trip in the right order.":{"src":"audio/6ecd1a2b7a01d42c.mp3","starts":[0,0.267,0.348,0.464,1.242,1.498,1.602,1.834,1.927,2.043,2.264]},"The little rocket flew back to the warm Sun and rested.":{"src":"audio/68ec94f23b824367.mp3","starts":[0,0.255,0.534,0.917,1.161,1.358,1.474,1.579,1.892,2.287,2.543]},"A little paper rocket floated near the big, warm Sun.":{"src":"audio/5b4a06b0d758622f.mp3","starts":[0,0.174,0.441,0.789,1.184,1.567,1.788,1.95,2.252,2.659]},"The Little Digger Builds a Park.":{"src":"audio/bf4e4826a718f398.mp3","starts":[0,0.267,0.546,0.906,1.173,1.254]},"Today the big machines would build a park.":{"src":"audio/79eb433540b83974.mp3","starts":[0,0.464,0.58,0.801,1.173,1.335,1.567,1.637]},"A little yellow digger looked at an empty, sandy lot.":{"src":"audio/0faa3f67aeaff9ba.mp3","starts":[0,0.174,0.441,0.731,1.045,1.289,1.382,1.509,1.834,2.194]},"Which machine pushed the sand flat?":{"src":"audio/ddc7d0ca344ad9c5.mp3","starts":[0,0.325,0.72,0.987,1.103,1.428]},"First the little digger dug a hole. Scoop, lift, drop.":{"src":"audio/d78bb0756abcdaf5.mp3","starts":[0,0.348,0.464,0.72,1.08,1.312,1.405,2.009,2.74,3.413]},"Then the bulldozer pushed the sand. Its wide blade made it smooth and flat.":{"src":"audio/6d648eb0786b658f.mp3","starts":[0,0.255,0.372,0.964,1.219,1.335,2.31,2.577,2.879,3.228,3.425,3.553,4.18,4.528]},"The dump truck came. It tipped up and poured out grey gravel.":{"src":"audio/3685818c9286f235.mp3","starts":[0,0.209,0.453,0.72,1.312,1.509,1.811,1.974,2.113,2.357,2.519,2.74]},"What is gravel?":{"src":"audio/12a956c764c24672.mp3","starts":[0,0.232,0.383]},"The cement mixer turned and turned. Then it poured smooth, wet cement.":{"src":"audio/6e17de79e24c8857.mp3","starts":[0,0.221,0.569,0.998,1.556,1.834,2.914,3.146,3.262,3.622,4.47,4.83]},"The tall crane lifted a little play house. Slowly, gently, down it came.":{"src":"audio/f89fa1b9904a4836.mp3","starts":[0,0.221,0.557,0.906,1.219,1.3,1.544,1.788,2.485,3.344,4.029,4.284,4.4]},"The path is still soft and bumpy. Which machine could make it flat?":{"src":"audio/978e90d9f76c9dcb.mp3","starts":[0,0.232,0.546,0.639,0.94,1.289,1.428,2.101,2.38,2.728,2.926,3.111,3.228]},"The road roller rolled the path. Roll, roll, roll, until it was smooth.":{"src":"audio/31a69a1554769c56.mp3","starts":[0,0.255,0.522,0.94,1.219,1.335,2.148,2.972,3.785,4.586,5.004,5.108,5.271]},"Why did the crane lift the play house slowly?":{"src":"audio/2e23ca3a008cadfb.mp3","starts":[0,0.244,0.383,0.488,0.778,0.987,1.091,1.358,1.625]},"The work was done. There was a path, a slide, and a little play house.":{"src":"audio/26dc2a78bf3a89a4.mp3","starts":[0,0.197,0.418,0.604,1.103,1.324,1.474,1.567,1.974,2.113,2.659,2.844,2.914,3.17,3.402]},"What came first — the crane, the digging, or the road roller?":{"src":"audio/a6d7613f9a38f41b.mp3","starts":[0,0.279,0.557,1.196,1.347,1.962,2.125,2.786,3.03,3.158,3.39]},"How do you think the little digger felt when the park was done?":{"src":"audio/1705c5f36a9a7709.mp3","starts":[0,0.232,0.325,0.453,0.662,0.778,1.045,1.405,1.625,1.776,1.892,2.148,2.357]},"Each machine did its own job. Together, they built a park.":{"src":"audio/08c1d1e44118dd8b.mp3","starts":[0,0.325,0.673,0.824,0.975,1.161,1.753,2.508,2.694,2.937,3.007]},"The land is bumpy and bare. What do you think the machines will do first?":{"src":"audio/5e3ab2e5022afe53.mp3","starts":[0,0.244,0.522,0.673,1.242,1.509,2.299,2.496,2.589,2.717,2.926,3.042,3.402,3.576,3.75]},"The little digger parked by the slide and rested.":{"src":"audio/31a03f4cb0106230.mp3","starts":[0,0.232,0.499,0.836,1.115,1.254,1.358,1.741,1.904]},"On Monday she crawled to one soft ball. Roll, roll.":{"src":"audio/ca7ace53d89e88a8.mp3","starts":[0,0.267,0.65,0.871,1.219,1.416,1.788,2.194,2.856,3.657]},"Nadine is Noah's baby sister. She could not walk yet. She could only crawl.":{"src":"audio/9ddcefb0462155b5.mp3","starts":[0,0.522,0.697,1.068,1.416,2.252,2.438,2.624,2.798,3.077,3.599,3.785,3.959,4.226]},"Nadine loves to crawl. Where do you think she will go this week?":{"src":"audio/972e7bd9bd26eddd.mp3","starts":[0,0.511,0.743,0.894,1.486,1.695,1.788,1.904,2.125,2.252,2.438,2.589,2.786]},"What did Nadine find in the bath?":{"src":"audio/abf4dab0a840f139.mp3","starts":[0,0.232,0.383,0.801,1.057,1.138,1.242]},"On Tuesday she crawled to two wooden blocks. Bang, bang.":{"src":"audio/d54dbe73982898cf.mp3","starts":[0,0.232,0.755,0.964,1.265,1.382,1.579,1.869,2.38,2.868]},"On Wednesday she found three yellow ducks in the bath. Splash, splash, splash.":{"src":"audio/0be18497aedbf552.mp3","starts":[0,0.232,0.697,0.894,1.149,1.416,1.73,2.02,2.113,2.218,2.984,3.82,4.586]},"On Thursday she crawled to four picture books. Pat, pat, pat, pat.":{"src":"audio/b2ab6b953958a783.mp3","starts":[0,0.255,0.813,1.022,1.324,1.463,1.718,2.067,2.728,3.332,3.913,4.54]},"On Friday she found five shiny pots. Clang, clang, clang, clang, clang!":{"src":"audio/091c8841456f04e8.mp3","starts":[0,0.255,0.697,0.871,1.161,1.556,1.939,2.624,3.158,3.669,4.191,4.725]},"Each day she went to more things. What might happen on Saturday?":{"src":"audio/3a9d6910e8cb17d6.mp3","starts":[0,0.348,0.604,0.778,0.975,1.115,1.358,2.067,2.276,2.496,2.868,3.019]},"How do you think Nadine felt after crawling everywhere?":{"src":"audio/438faee2d088ab50.mp3","starts":[0,0.221,0.313,0.43,0.685,1.045,1.37,1.683,2.067]},"On Saturday she crawled everywhere. Under the table, behind the sofa, and round and round the rug.":{"src":"audio/7af67d0011f5cd1f.mp3","starts":[0,0.279,0.894,1.115,1.521,2.624,2.902,3.019,3.924,4.412,4.54,5.375,5.7,6.281,6.548,6.931,7.082]},"On Sunday Mama wrapped her in a soft blanket. Nadine had a long, long nap.":{"src":"audio/dce8484885f4bfa7.mp3","starts":[0,0.255,0.755,1.045,1.312,1.428,1.533,1.614,1.974,3.1,3.564,3.738,3.855,4.609,5.027]},"What does wrapped mean?":{"src":"audio/b85e00ff99c93333.mp3","starts":[0,0.244,0.441,0.859]},"What came first — the long nap, the ball, or the pots?":{"src":"audio/85a5c5ac4d72e6bc.mp3","starts":[0,0.29,0.58,1.033,1.161,1.463,1.927,2.09,2.543,2.74,2.856]},"When she woke up, Nadine stood up. One step, two steps, three. She walked to Noah!":{"src":"audio/ede4c48655ea57ed.mp3","starts":[0,0.267,0.453,0.743,1.057,1.498,1.765,2.206,2.508,3.077,3.332,4.098,5.039,5.271,5.55,5.666]},"How do you think Noah felt when Nadine walked to him?":{"src":"audio/32ffc144afe45d42.mp3","starts":[0,0.232,0.325,0.453,0.72,1.045,1.312,1.509,1.927,2.194,2.334]},"Nadine was not a crawling baby any more. She was a walking girl.":{"src":"audio/fb7070e2fbc56f25.mp3","starts":[0,0.476,0.685,0.894,0.975,1.428,1.753,1.927,2.635,2.833,3.007,3.123,3.622]},"Noah's Very Hungry Week.":{"src":"audio/b6c534bef098af51.mp3","starts":[0,0.441,0.766,1.091]},"On Sunday night, Noah went to bed with an empty tummy.":{"src":"audio/c89518d0e7a54aa7.mp3","starts":[0,0.255,0.65,0.94,1.277,1.474,1.625,1.916,2.101,2.229,2.566]},"When Noah wakes up, how do you think his tummy will feel?":{"src":"audio/e670dca2519fe182.mp3","starts":[0,0.255,0.534,0.778,1.196,1.324,1.416,1.521,1.707,1.846,2.125,2.322]},"On Monday he woke up hungry. He ate one yellow banana.":{"src":"audio/7a9327a3363e1f07.mp3","starts":[0,0.244,0.592,0.72,0.952,1.103,1.776,1.95,2.148,2.299,2.566]},"On Tuesday he ate two crunchy carrots.":{"src":"audio/7070644da42ea54b.mp3","starts":[0,0.209,0.697,0.824,1.01,1.231,1.591]},"On Wednesday he ate three slices of juicy watermelon.":{"src":"audio/79e767406fc735c1.mp3","starts":[0,0.244,0.731,0.871,1.068,1.347,1.881,2.02,2.368]},"What did Noah eat on Tuesday?":{"src":"audio/553bacd025c55ebc.mp3","starts":[0,0.232,0.395,0.639,0.801,0.906]},"On Thursday he ate four red strawberries.":{"src":"audio/004e5daeb2450e04.mp3","starts":[0,0.232,0.673,0.824,1.057,1.324,1.533]},"On Saturday there is a party. What might Noah eat there?":{"src":"audio/1464fe48b84e35c3.mp3","starts":[0,0.267,0.789,0.975,1.103,1.196,1.916,2.136,2.345,2.647,2.844]},"On Friday he ate five little tomatoes. But he was still hungry.":{"src":"audio/ab2cd3c2f72171ec.mp3","starts":[0,0.267,0.743,0.882,1.091,1.428,1.695,2.589,2.798,2.914,3.077,3.425]},"On Saturday he ate cake, ice cream, sweets, chips, a cookie, and a big pink cupcake!":{"src":"audio/cf363f99d2d4fb3c.mp3","starts":[0,0.279,0.906,1.091,1.358,2.032,2.38,2.972,3.924,4.702,4.876,5.666,5.898,6.049,6.444,6.827]},"Why did Noah's tummy hurt?":{"src":"audio/c74be8356f752095.mp3","starts":[0,0.255,0.406,0.731,1.08]},"That night, Noah had a tummy ache. Ouch.":{"src":"audio/8a6790c2050de6cf.mp3","starts":[0,0.348,0.639,0.975,1.138,1.219,1.614,2.043]},"On Sunday he ate a warm bowl of soup with green peas. His tummy felt calm again.":{"src":"audio/a3d05bbce28f24e8.mp3","starts":[0,0.255,0.685,0.836,1.045,1.115,1.405,1.637,1.753,2.032,2.218,2.531,3.437,3.669,3.994,4.249,4.574]},"Mama measured him on the wall. Noah had grown taller!":{"src":"audio/d8cc11a938ce55b8.mp3","starts":[0,0.372,0.685,0.848,0.952,1.068,1.869,2.322,2.496,2.81]},"How do you think Noah felt when he saw how tall he was?":{"src":"audio/6f3176270f8fcb2b.mp3","starts":[0,0.221,0.313,0.43,0.708,1.033,1.265,1.44,1.567,1.834,1.997,2.322,2.45]},"Noah was not a little boy any more. He was a big, strong brother.":{"src":"audio/7398145e62998b69.mp3","starts":[0,0.418,0.65,0.859,0.917,1.161,1.44,1.614,2.09,2.287,2.473,2.635,3.077,3.541]},"What came first — the soup, the banana, or the party?":{"src":"audio/31124d2fe19efa8e.mp3","starts":[0,0.279,0.58,1.347,1.498,2.101,2.241,2.984,3.193,3.32]},"Nadine's Very Busy Week.":{"src":"audio/2c9f1af09d5a8b91.mp3","starts":[0,0.557,0.871,1.161]},"How Lava Builds an Island.":{"src":"audio/339274b3c390db97.mp3","starts":[0,0.279,0.569,0.824,0.964]},"Tectonic plates pulled apart. A crack opened. Pressure built.":{"src":"audio/f608671e522a04d3.mp3","starts":[0,0.58,0.882,1.149,2.171,2.368,2.81,3.46,3.913]},"Deep under the ocean, Blippi, Terrence, and Biscuit Monster watched the seabed.":{"src":"audio/1fd9de00ee97ba77.mp3","starts":[0,0.348,0.546,0.72,1.312,1.881,2.392,2.543,2.891,3.379,3.715,3.831]},"Super-hot liquid rock escaped the mantle. Magma rose. It burst into the freezing ocean.":{"src":"audio/1c52ff6513e75922.mp3","starts":[0,0.418,0.639,0.952,1.277,1.695,1.811,2.473,2.972,3.599,3.796,4.11,4.296,4.423,4.911]},"What sound did the water make when it met the hot rock?":{"src":"audio/c5e3c6c8421e6726.mp3","starts":[0,0.325,0.604,0.731,0.848,1.196,1.405,1.567,1.683,1.904,2.032,2.31]},"Eruption after eruption, the underwater mountain grew taller. Thousands of years.":{"src":"audio/e2a02154e1ae6b9c.mp3","starts":[0,0.569,0.824,1.614,1.823,2.403,2.717,2.949,3.68,4.261,4.412]},"Sssss! Cold water met molten rock. Giant black pillow basalt formed under the sea.":{"src":"audio/0a66e6b2f779f5bd.mp3","starts":[0,1.312,1.66,2.043,2.299,2.705,3.541,3.924,4.238,4.586,5.097,5.433,5.642,5.77]},"The mountain keeps growing. What might happen when it reaches the waves?":{"src":"audio/478e0311aed7ac5b.mp3","starts":[0,0.267,0.615,0.917,1.544,1.765,1.997,2.368,2.531,2.647,3.019,3.146]},"The rock broke through the waves. Clouds of steam shot into the sky. Terrence covered his ears.":{"src":"audio/e613b03221340ee0.mp3","starts":[0,0.232,0.522,0.766,0.987,1.091,1.823,2.194,2.31,2.682,2.914,3.1,3.204,4.075,4.551,4.911,5.12]},"A crack is open in the seabed. What do you think will come out?":{"src":"audio/75a879d9adf7c382.mp3","starts":[0,0.197,0.522,0.673,0.998,1.091,1.219,2.02,2.218,2.31,2.438,2.635,2.81,2.995]},"Why did the lava turn hard?":{"src":"audio/5d9e6290c276993b.mp3","starts":[0,0.255,0.395,0.522,0.871,1.161]},"The volcanic soil cooled. Green seeds arrived on the wind. An island was born.":{"src":"audio/d6d37e8dbd318439.mp3","starts":[0,0.209,0.766,1.138,1.8,2.125,2.438,2.775,2.868,2.972,3.483,3.738,4.145,4.342]},"What is magma?":{"src":"audio/25769205c9154594.mp3","starts":[0,0.279,0.464]},"Biscuit Monster sniffed a leaf. Blippi said, From a crack in the floor to a home for plants.":{"src":"audio/7d790bbf9a560c8c.mp3","starts":[0,0.488,0.998,1.416,1.498,2.299,2.763,3.448,3.68,3.796,4.168,4.272,4.4,4.899,5.178,5.259,5.573,5.782]},"What came first — the green seeds, the crack, or the steam in the sky?":{"src":"audio/32fefea81a170b4d.mp3","starts":[0,0.302,0.604,1.324,1.486,1.834,2.473,2.647,3.216,3.448,3.564,3.831,3.913,4.017]},"How do you think they felt when the green seeds grew?":{"src":"audio/ae8acff1950f0270.mp3","starts":[0,0.221,0.313,0.43,0.639,0.836,1.057,1.219,1.347,1.672,1.997]},"Look at the pictures. Tell how the island was built.":{"src":"audio/4d753b7f449e01e2.mp3","starts":[0,0.244,0.337,0.464,1.231,1.474,1.625,1.776,2.055,2.229]},"The Life of a Star.":{"src":"audio/2013764fdfc35296.mp3","starts":[0,0.244,0.464,0.569,0.685]},"Crack. Rise. Steam. Pile. Breach. Cool. Life. That is how lava builds an island.":{"src":"audio/9ea91192243516fd.mp3","starts":[0,0.824,1.591,2.473,3.309,4.249,5.213,6.281,6.525,6.641,6.896,7.268,7.558,7.709]},"Blippi, Terrence, and Biscuit Monster floated in dark space. A cold cloud of gas hung still.":{"src":"audio/21b9addcdbeb2fcb.mp3","starts":[0,0.766,1.312,1.486,1.846,2.31,2.728,2.856,3.17,4.203,4.423,4.783,5.12,5.271,5.666,5.979]},"Hydrogen dust pulled together. Gravity got stronger and stronger.":{"src":"audio/6cbc7d9792b4ff5c.mp3","starts":[0,0.592,0.848,1.08,1.765,2.241,2.461,2.984,3.158]},"The cloud is squeezing tight. What do you think it will become?":{"src":"audio/b187eb1b94709514.mp3","starts":[0,0.232,0.522,0.615,1.057,1.579,1.776,1.881,2.009,2.229,2.31,2.485]},"The gas balled up. The middle got hot. Ten thousand degrees. One hundred thousand degrees!":{"src":"audio/3a742c9007bbdb18.mp3","starts":[0,0.232,0.569,0.882,1.242,1.428,1.718,1.997,2.81,3.17,3.587,4.389,4.656,4.981,5.375]},"Ignition! A baby star turned on its light. Terrence clapped.":{"src":"audio/d767527c677a5afe.mp3","starts":[0,1.138,1.324,1.672,2.009,2.299,2.415,2.589,2.902,3.367]},"The yellow star burned clean fuel for a very long time. It pushed heat out. Gravity pulled in.":{"src":"audio/47cb1dea2292fa75.mp3","starts":[0,0.232,0.557,0.964,1.289,1.683,2.125,2.31,2.438,2.81,3.088,3.982,4.18,4.54,4.807,5.526,6.06,6.385]},"Push out. Pull in. Perfect balance. Blippi called it a happy star.":{"src":"audio/4a0d5dff572658f8.mp3","starts":[0,0.383,0.882,1.242,1.683,2.055,2.81,3.181,3.437,3.541,3.622,3.947]},"What colour was the star when it was in balance?":{"src":"audio/3f9b763a47233290.mp3","starts":[0,0.302,0.639,0.801,0.917,1.312,1.474,1.579,1.741,1.892]},"The hydrogen fuel ran low. The middle shrank. The outside swelled huge and red.":{"src":"audio/3d17741105c8c6f2.mp3","starts":[0,0.232,0.731,1.068,1.324,1.904,2.067,2.357,3.239,3.471,4.04,4.389,4.83,5.027]},"The red giant swallowed the nearest planets. Biscuit Monster hid behind Terrence.":{"src":"audio/54a00b198f15a039.mp3","starts":[0,0.244,0.476,0.848,1.254,1.358,1.695,2.577,3.042,3.46,3.68,4.052]},"The fuel is almost gone. What might happen next?":{"src":"audio/c640c3d35cd3e6cc.mp3","starts":[0,0.232,0.511,0.627,0.964,1.718,1.927,2.136,2.461]},"Why did the star boom?":{"src":"audio/18fa9e04c6533274.mp3","starts":[0,0.267,0.418,0.534,0.94]},"Core collapse! BOOM. The star blasted heavy metals into the galaxy.":{"src":"audio/9a337642c7471d31.mp3","starts":[0,0.36,1.173,2.125,2.31,2.705,3.193,3.483,3.889,4.133,4.249]},"All that remained was a tiny, dense neutron core, spinning in the dark.":{"src":"audio/179d1db5719fc5d1.mp3","starts":[0,0.232,0.418,0.859,1.022,1.138,1.602,2.009,2.543,3.17,3.692,3.796,3.901]},"What does gravity mean?":{"src":"audio/eb5234c246a4cc4d.mp3","starts":[0,0.221,0.406,0.871]},"How do you think Terrence felt at the end?":{"src":"audio/801db73a2a8ce7a1.mp3","starts":[0,0.209,0.302,0.418,0.639,0.975,1.184,1.277,1.416]},"What came first — the yellow star, the cloud, or the boom?":{"src":"audio/5c1d6bfe58b8aef7.mp3","starts":[0,0.29,0.604,1.358,1.509,1.846,2.485,2.67,3.332,3.553,3.68]},"Look at the pictures. Tell the life of the star in the right order.":{"src":"audio/07357f6af73a9293.mp3","starts":[0,0.255,0.337,0.453,1.277,1.521,1.637,1.846,1.95,2.055,2.403,2.519,2.67,2.937]},"The Great Planetary Size Index.":{"src":"audio/bd6af8c2eaf76494.mp3","starts":[0,0.255,0.522,1.219,1.637]},"Blippi whispered, Five steps. Cloud, baby star, yellow star, red giant, boom.":{"src":"audio/f2272ac109636062.mp3","starts":[0,0.383,1.207,1.556,2.264,2.717,3.019,3.68,4.017,4.679,4.934,5.596]},"Blippi, Terrence, and Biscuit Monster lined up the planets by size. Smallest to biggest.":{"src":"audio/45c4f193a6f48011.mp3","starts":[0,0.546,1.045,1.196,1.556,2.02,2.287,2.415,2.519,2.984,3.204,3.971,4.621,4.748]},"Which planet do you think is the smallest?":{"src":"audio/99be10526a071813.mp3","starts":[0,0.325,0.685,0.778,0.906,1.115,1.231,1.347]},"Category A. The Rocky Scouts. Small and solid.":{"src":"audio/145ebef70a75ac03.mp3","starts":[0,0.72,1.207,1.416,1.765,2.334,2.833,3.007]},"Mercury. Four thousand eight hundred seventy-nine kilometers across. A pocket-sized rock. Zero air.":{"src":"audio/be1b9fbe9026270e.mp3","starts":[0,0.929,1.207,1.672,1.881,2.287,2.659,2.891,3.46,4.481,4.656,5.039,5.41,6.037,6.513]},"Mars. Six thousand seven hundred seventy-nine kilometers. Red dust. Two tiny moons.":{"src":"audio/edcf05fca56de5fb.mp3","starts":[0,0.94,1.289,1.8,2.159,2.543,2.972,3.251,4.214,4.481,5.259,5.596,6.002]},"Venus. Twelve thousand one hundred four kilometers. Heavy yellow clouds. A runaway hot oven.":{"src":"audio/b39ed0434b6cdf0b.mp3","starts":[0,1.01,1.37,1.858,2.02,2.415,2.659,3.669,3.959,4.296,5.097,5.283,5.77,6.002]},"Which rocky planet has zero air?":{"src":"audio/9196e87a5761bc23.mp3","starts":[0,0.313,0.615,0.964,1.138,1.556]},"Earth. Twelve thousand seven hundred forty-two kilometers. Liquid water. Nitrogen air. Life confirmed.":{"src":"audio/e65fe199b1c04834.mp3","starts":[0,0.488,0.824,1.289,1.602,1.916,2.194,2.403,3.448,3.843,4.481,5.097,5.851,6.165]},"Category B. The Ice Giants. Frozen gas and water.":{"src":"audio/6f889938108f159c.mp3","starts":[0,0.627,1.184,1.382,1.683,2.461,2.949,3.239,3.355]},"Neptune. Forty-nine thousand two hundred forty-four kilometers. Methane blue. Super-fast wind storms.":{"src":"audio/fbd1bf77548eb762.mp3","starts":[0,1.242,1.649,1.939,2.438,2.682,2.995,3.309,3.541,4.83,5.352,6.293,6.699,7.001,7.21]},"Why are Neptune and Uranus called ice giants?":{"src":"audio/25b2d9a27d5aafdc.mp3","starts":[0,0.255,0.418,0.824,0.94,1.382,1.695,1.997]},"Uranus. Fifty thousand seven hundred twenty-four kilometers. A cyan ice ball. Tilted on its side.":{"src":"audio/8ed047909aeb544c.mp3","starts":[0,1.347,1.776,2.241,2.589,2.995,3.355,3.611,4.795,5.016,5.573,5.863,6.409,6.803,6.92,7.082]},"Category C. The Gas Titans. Massive and made of spinning gas.":{"src":"audio/e7d8a2421df7ebd9.mp3","starts":[0,0.604,1.219,1.393,1.718,2.519,3.17,3.402,3.634,3.773,4.249]},"Saturn. One hundred sixteen thousand four hundred sixty kilometers. Light hydrogen. Wide ice rings.":{"src":"audio/09bae6ecee3d5f83.mp3","starts":[0,1.219,1.474,1.8,2.241,2.728,2.937,3.239,3.634,4.865,5.19,6.037,6.397,6.699]},"What does giant mean?":{"src":"audio/2a3085ea493eab17.mp3","starts":[0,0.232,0.464,0.871]},"Jupiter. One hundred thirty-nine thousand eight hundred twenty kilometers. The king. Ninety-five moons. A giant red storm.":{"src":"audio/dc4efaeed79d9cd8.mp3","starts":[0,1.219,1.463,1.73,2.009,2.241,2.821,3.077,3.367,3.727,4.841,5.062,5.956,6.316,6.641,7.512,7.744,8.22,8.475]},"What is smallest to biggest — Jupiter, Mercury, or Earth?":{"src":"audio/14130f64eab99d85.mp3","starts":[0,0.232,0.36,0.871,0.998,1.695,2.438,3.158,3.413]},"How do you think Biscuit Monster felt next to giant Jupiter?":{"src":"audio/305bb2d5d5629b80.mp3","starts":[0,0.197,0.29,0.395,0.627,0.987,1.428,1.707,1.962,2.125,2.473]},"Look at the pictures. Sort them from smallest to biggest.":{"src":"audio/a33519622ae76a38.mp3","starts":[0,0.267,0.348,0.464,1.324,1.637,1.8,2.02,2.577,2.728]},"Slicing Planet Earth.":{"src":"audio/94a7b22c550e9ee6.mp3","starts":[0,0.569,0.929]},"Terrence tapped the list. Rocky scouts. Ice giants. Gas titans. Size is a kind of map.":{"src":"audio/c4f1bb821c554e6e.mp3","starts":[0,0.464,0.755,0.871,1.486,1.892,2.728,3.1,3.727,4.122,5.074,5.677,5.863,5.991,6.351,6.513]},"Blippi held a clay Earth. Terrence said, Let us slice it. Biscuit Monster licked his lips. Not for eating!":{"src":"audio/7df8452b09d760d8.mp3","starts":[0,0.441,0.685,0.766,1.091,1.416,1.869,2.403,2.624,2.763,3.286,3.727,4.145,4.528,4.76,4.911,5.492,5.747,5.944]},"Layer zero. The crust. We stand on cold, hard rock.":{"src":"audio/05f9b8f147104838.mp3","starts":[0,0.43,1.08,1.265,1.997,2.194,2.543,2.717,3.077,3.379]},"Continents of granite. Oceans of deep blue water. The crust is thin, like the skin of an apple.":{"src":"audio/5806aa720242e6c2.mp3","starts":[0,0.592,0.743,1.416,1.881,2.032,2.264,2.485,3.077,3.251,3.622,3.762,4.354,4.586,4.714,5.027,5.132,5.329]},"If we drill down under the crust, what do you think we will find?":{"src":"audio/fbde1cc99f838cdf.mp3","starts":[0,0.197,0.337,0.58,0.801,0.987,1.091,1.753,1.916,1.997,2.113,2.334,2.438,2.647]},"Layer one. The upper mantle. Drill down. The rocks turn red-hot.":{"src":"audio/9d59d480b73a619f.mp3","starts":[0,0.441,1.045,1.254,1.556,2.264,2.682,3.448,3.669,4.04,4.516,4.807]},"What is the thin outer layer called?":{"src":"audio/8ae08371ab3281f6.mp3","starts":[0,0.232,0.36,0.488,0.778,1.045,1.358]},"Giant plates slide on soft, flowing stone. This is where magma sleeps.":{"src":"audio/14db35a22894f353.mp3","starts":[0,0.441,0.789,1.161,1.324,1.788,2.276,3.1,3.367,3.495,3.762,4.261]},"Layer two. The lower mantle. Crushing pressure! The rock cannot melt. Gravity squeezes it tight.":{"src":"audio/05a756009c13a487.mp3","starts":[0,0.464,1.3,1.521,1.939,2.752,3.286,4.377,4.609,4.992,5.468,6.235,6.792,7.361,7.5]},"Layer three. The outer core. A swirling sea of liquid iron and nickel.":{"src":"audio/f8011cc3d18679d3.mp3","starts":[0,0.453,1.521,1.8,2.229,3.228,3.46,4.122,4.447,4.621,4.992,5.352,5.515]},"It flows and churns. This moving metal builds Earth's magnetic shield. It blocks solar storms.":{"src":"audio/673f2deea132cf40.mp3","starts":[0,0.244,0.72,0.882,1.753,2.067,2.473,2.81,3.17,3.506,4.017,5.016,5.213,5.642,6.095]},"Why does Earth need a magnetic shield?":{"src":"audio/a4e07218a53894dc.mp3","starts":[0,0.255,0.488,0.789,0.987,1.057,1.533]},"Layer four. The inner core. Six thousand degrees. As hot as the surface of the Sun!":{"src":"audio/3cae7993bb899935.mp3","starts":[0,0.441,1.091,1.37,1.718,2.45,2.821,3.239,3.994,4.296,4.598,4.76,4.923,5.422,5.538,5.7]},"A solid ball of white-hot iron, locked under billions of tons of weight. The heart of the world.":{"src":"audio/9a9b1ed2e0ff1641.mp3","starts":[0,0.221,0.673,0.952,1.138,1.382,1.695,2.392,2.752,3.077,3.657,3.796,4.11,4.249,4.76,4.969,5.224,5.341,5.468]},"The black lava cooled into hard basalt. Waves smashed against the new cliffs.":{"src":"audio/e5a1f7c939cc7f81.mp3","starts":[0,0.209,0.534,0.906,1.196,1.463,1.765,2.74,3.1,3.553,3.843,3.959,4.133]},"Terrence counted. Crust. Mantle. Outer core. Inner core. Four layers under our feet.":{"src":"audio/11ff712640666b3b.mp3","starts":[0,0.464,1.057,1.834,2.67,3.077,3.704,4.087,4.725,5.039,5.399,5.631,5.793]},"How do you think Biscuit Monster felt at the hot heart?":{"src":"audio/43dedd6b4425c1a3.mp3","starts":[0,0.244,0.348,0.488,0.743,1.138,1.625,1.881,1.974,2.101,2.357]},"Look at the pictures. Tell the layers from the outside in.":{"src":"audio/3892cab7d2f14284.mp3","starts":[0,0.255,0.337,0.453,1.312,1.567,1.683,1.997,2.159,2.287,2.856]},"What comes first if you start on the outside — the inner core, the crust, or the outer core?":{"src":"audio/d4a1ed877c852a07.mp3","starts":[0,0.29,0.627,1.057,1.173,1.335,1.602,1.707,1.916,3.042,3.239,3.541,4.145,4.307,4.923,5.143,5.306,5.642]},"Noah and the Solar Eclipse.":{"src":"audio/5a479225a29bc342.mp3","starts":[0,0.511,0.72,0.824,1.161]},"Blippi held up dark glasses. Never look at the Sun with bare eyes. Special glasses keep us safe.":{"src":"audio/b09919d50badf1d7.mp3","starts":[0,0.43,0.685,0.848,1.103,2.218,2.577,2.775,2.879,2.995,3.216,3.402,3.704,4.447,4.934,5.433,5.7,5.851]},"Noah, baby sister Nadine, SpongeBob, Squidward, and Blippi sat on a quiet hill. The Sun was round and bright.":{"src":"audio/db3d75067fd89783.mp3","starts":[0,0.697,1.045,1.405,2.218,3.239,4.029,4.238,4.656,4.923,5.039,5.12,5.538,6.153,6.327,6.583,6.85,7.372,7.616]},"The Moon slid in. A little bite of the Sun was gone. SpongeBob whispered, Wow.":{"src":"audio/24847fe77beeb748.mp3","starts":[0,0.267,0.569,0.894,1.37,1.544,1.834,2.101,2.206,2.322,2.566,2.775,3.39,4.145,4.969]},"Why did they wear special glasses?":{"src":"audio/2545e88f7aa9ad65.mp3","starts":[0,0.232,0.372,0.511,0.755,1.184]},"More and more of the Sun was covered. The hill went grey. Squidward said, It is getting dim.":{"src":"audio/6f3cd67777adaaa8.mp3","starts":[0,0.337,0.464,0.673,0.778,0.906,1.173,1.382,2.519,2.728,2.995,3.228,3.994,4.644,5.654,5.851,6.014,6.374]},"What is the corona?":{"src":"audio/3797136b0fc75ba4.mp3","starts":[0,0.255,0.418,0.546]},"The Moon covered the Sun. A white ring shone around the black circle. That ring is the corona.":{"src":"audio/24fc4298b7cef385.mp3","starts":[0,0.244,0.557,0.94,1.068,1.858,2.032,2.334,2.635,3.03,3.274,3.379,3.704,4.725,5.085,5.399,5.55,5.7]},"Day felt like night. Nadine held Noah's hand. Nobody looked up without the glasses.":{"src":"audio/43e64e51b649d3a9.mp3","starts":[0,0.325,0.569,0.789,1.614,2.113,2.403,2.74,3.541,3.959,4.214,4.331,4.609,4.714]},"The Moon is still moving. What do you think will happen next?":{"src":"audio/6211d6988c272d58.mp3","starts":[0,0.209,0.418,0.511,0.789,1.591,1.765,1.846,1.962,2.159,2.345,2.659]},"A bead of gold popped out. The Sun was coming back. Blippi cheered.":{"src":"audio/9737af3aaa3ad544.mp3","starts":[0,0.186,0.395,0.546,0.848,1.184,1.741,1.927,2.183,2.38,2.74,3.506,3.936]},"Light poured over the hill. Birds called. Squidward took off his glasses and blinked.":{"src":"audio/8c9eb3acf144ef85.mp3","starts":[0,0.313,0.615,0.824,0.94,1.509,1.927,2.694,3.193,3.39,3.553,3.704,4.191,4.354]},"Why did the hill go grey?":{"src":"audio/d70fd18f939f8b40.mp3","starts":[0,0.232,0.372,0.499,0.766,0.987]},"How do you think Noah felt when Nadine held his hand?":{"src":"audio/1ffb4953c2dafdf2.mp3","starts":[0,0.221,0.313,0.43,0.697,1.022,1.265,1.451,1.858,2.078,2.229]},"What came first — the white ring, the bright Sun, or the grey hill?":{"src":"audio/675c6f18bf5d88f0.mp3","starts":[0,0.302,0.604,1.324,1.474,1.741,2.299,2.45,2.775,3.274,3.471,3.622,3.959]},"Look at the pictures. Tell the eclipse in the right order.":{"src":"audio/f642791f28020f90.mp3","starts":[0,0.244,0.325,0.453,1.219,1.451,1.591,2.009,2.101,2.218,2.45]},"The Moon moved on. The Sun was round and bright again. Nadine clapped. The eclipse was done.":{"src":"audio/aa516ba5a47786fc.mp3","starts":[0,0.267,0.58,0.964,1.533,1.8,2.194,2.473,3.065,3.344,3.68,4.737,5.317,6.304,6.525,7.105,7.396]},"Something is going to slide in front of the Sun. What do you think it is?":{"src":"audio/46ba7bf51f8cde6e.mp3","starts":[0,0.464,0.604,0.813,0.917,1.265,1.382,1.544,1.637,1.753,2.577,2.763,2.844,2.961,3.181,3.297]}});
